import {preparationControls} from './market-actions-ui.js';
import {AREAS} from './world.js';
import {militaryDestinations} from './military.js';
export function renderMilitaryForm(s,id,card={},cards={}){const p=s.players[s.current],gain=card.armyGain??1,maxMoves=card.maxMoves??2,destinations=[...new Set([...militaryDestinations(s),...(card.destinationOverride?[card.destinationOverride]:[])])];
 const from=`<option value="reserve">待命军队（行动前${p.resources[6]}）</option>`+Object.entries(AREAS).map(([r,a])=>`<option value="${r}">${a.name}（现有${s.regions[r].armies[s.current]}）</option>`).join('');
 const shown=card.onlyDestination?[card.onlyDestination]:s.config.wit?Object.keys(AREAS):destinations;const to='<option value="">不移动</option>'+shown.map(r=>`<option value="${r}">${AREAS[r].name}${destinations.includes(r)?'':' · 需SP'}</option>`).join('');
 return `<section id="basic-form" data-card-id="${id}" class="flow-panel"><b>${card.name||'军事增援'} · 自动结算</b>${preparationControls(s,card,cards)}<p>${gain?'先获得'+gain+'军队。':''}依次移动${card.minMoves?card.minMoves+'～':''}${maxMoves}次，每次支付${card.moveCost??5}资金。</p>${Array.from({length:maxMoves},(_,i)=>i).map(i=>`<fieldset><legend>第${i+1}次移动</legend><label>从<select data-military-from="${i}">${from}</select></label><label>到<select data-military-to="${i}">${to}</select></label>${s.config.wit?`<label><input type="checkbox" data-military-sp="${i}"> 消耗1 SP，允许移动到任意地区</label>`:''}</fieldset>`).join('')}<p class="minor">${card.onlyDestination?'目的地由本牌指定；':'目的地限本方利益地区或已记录本方基地的地区；'}出发地数量显示行动前状态，第二次移动会按第一次完成后的军队计算。</p>${card.resetAfterMoves?`<label>移动后可重置一个临时影响力<select id="market-reset"><option value="">不重置</option>${Object.entries(s.regions).flatMap(([region,r])=>r.temporary.map((owner,index)=>owner===s.current?`<option value="${region}:${index}">${AREAS[region].name} · 第${index+1}个临时位置</option>`:'')).join('')}</select></label><p>只能选择本次有军队移入的地区。</p>`:''}<p id="basic-preview" aria-live="polite"></p><button id="commit-basic" data-card-action="playBasicCard" data-id="${id}">结算并完成本次行动</button><p class="minor">SP按每次移动分别支付；其他特殊卡牌修正仍需手动处理。</p></section>`;
}
export function readMilitaryMoves(){return [...document.querySelectorAll('[data-military-to]')].filter(el=>el.value).map(el=>({from:document.querySelector(`[data-military-from="${el.dataset.militaryTo}"]`).value,to:el.value,spendSP:!!document.querySelector(`[data-military-sp="${el.dataset.militaryTo}"]`)?.checked}));}
export function militarySummary(preview){return `获得${preview.armyGain??1}军队，移动${preview.moves.length}次，支付${preview.cost}资金；结算后待命军队${preview.reserve}。`+preview.moves.map(m=>`${m.from==='reserve'?'待命区':AREAS[m.from].name} → ${AREAS[m.to].name}`).join('；');}
